    const getChannels = async (searchKeyword = '') => {
…
        try {
            const query = sb.groupChannel.createMyGroupChannelListQuery({
…
                includeEmpty: true,
                order: GroupChannelListOrder.LATEST_LAST_MESSAGE,
                ...(searchKeyword && {
                    searchFilter: {
                        query: searchKeyword,
                        fields: [GroupChannelSearchField.CHANNEL_NAME, GroupChannelSearchField.MEMBER_NICKNAME],
                    }
                })
            });

            // Get all channels in one go
            const channels: GroupChannel[] = [];
            while (query.hasNext) {
                // eslint-disable-next-line no-await-in-loop
                const batch = await query.next();
                channels.push(...batch);
            }

            return channels;
        } catch (error) {
            log.error('Error fetching channels', error);
            return [];
        }
    };

    // CS channels never appear in the main list. Non-staff see them via
    // <CalledTeamSection> pinned above; staff reach them via the Customer
    // Support filter row.
    const mainChannelList = useMemo(
        () => channelList.filter(ch => !isCustomerSuccessChannel(ch)),
        [channelList]
    );

    // This selects the first channel in the list, used when we don't have a channelUrl.
    // Uses mainChannelList so staff don't auto-land in (and instantly read) the CS
    // channel — it's reachable only via the Customer Support filter. Non-staff
    // customers with only a CS channel still land there so they're not left
    // with no selection.
