import { useState, useCallback } from 'react';
import { arrayMove } from '@dnd-kit/sortable';
import { enqueueSnackbar } from 'notistack';
import { ColumnSchema } from '../pathwayTypes';
import { useUpdatePathwayColumn } from '../pathwayApi';

interface UsePhaseReorderingParams {
    boardId: string | undefined;
    columns: ColumnSchema[];
    canEdit: boolean;
    refetchBoard: () => Promise<unknown>;
}

/**
 * Owns reordering phases (columns) by drag: the optimistic order shown while the
 * server catches up, the persistence (one `order` patch per column that moved),
 * and the refresh reconcile. Keeps this out of the large PathwayBoard component.
 */
export const usePhaseReordering = ({ boardId, columns, canEdit, refetchBoard }: UsePhaseReorderingParams) => {
    const { mutateAsync: patchColumn } = useUpdatePathwayColumn();
    const [optimisticColumns, setOptimisticColumns] = useState<ColumnSchema[] | null>(null);
    const [isReordering, setIsReordering] = useState(false);

    // Show the optimistic order while a reorder is in flight; otherwise the
    // server order. The finally block clears the overlay once the board refetches.
    const orderedColumns = optimisticColumns ?? columns;

    const reorderPhase = useCallback(async (activeColumnId: string, overColumnId: string) => {
        if (!boardId || !canEdit || activeColumnId === overColumnId) {
            return;
        }
        const oldIndex = orderedColumns.findIndex((column) => column.id === activeColumnId);
        const newIndex = orderedColumns.findIndex((column) => column.id === overColumnId);
        if (oldIndex < 0 || newIndex < 0) {
            return;
        }

        const reordered = arrayMove(orderedColumns, oldIndex, newIndex);
        // Persist the new index for every column whose position changed; `order` is
        // an absolute sort key, so the patches are independent and don't cascade.
        const movedColumns = reordered
            .map((column, index) => ({ column, index }))
            .filter(({ column, index }) => orderedColumns[index]?.id !== column.id);

        setOptimisticColumns(reordered);
        setIsReordering(true);
        try {
            await Promise.all(movedColumns.map(({ column, index }) =>
                patchColumn({ pathParams: { boardId, columnId: column.id }, body: { order: index } })));
        } catch {
            enqueueSnackbar('Failed to reorder phases. Please try again.', { variant: 'error' });
        } finally {
            // Reconcile against the server's canonical order, then drop the overlay.
            await refetchBoard().catch(() => undefined);
            setOptimisticColumns(null);
            setIsReordering(false);
        }
    }, [boardId, canEdit, orderedColumns, patchColumn, refetchBoard]);

    return { orderedColumns, isReordering, reorderPhase };
};

