import { CSSProperties, MouseEvent } from 'react';
import { useDraggable } from '@dnd-kit/core';
import { CSS } from '@dnd-kit/utilities';
import { PathwayUser, PathwayPhaseId } from '../pathwayTypes';
import { UserCard } from './UserCard';

import styles from './DraggableUserCard.module.scss';

type DraggableUserCardProps = {
    user: PathwayUser;
    boardId?: string;
    onClick?: (user: PathwayUser) => void;
    onSelect?: (user: PathwayUser) => void;
    onMoveUser?: (user: PathwayUser, targetPhaseId: PathwayPhaseId) => void;
    onArchiveUser?: (user: PathwayUser) => void;
    onRemoveUser?: (user: PathwayUser) => void;
    isCompleted?: boolean;
    isSelected?: boolean;
    onToggleSelect?: (user: PathwayUser, event: MouseEvent) => void;
    archiveLabel?: string;
    showResendEmail?: boolean;
};

export const DraggableUserCard = ({
    user,
    boardId,
    onClick,
    onSelect,
    onMoveUser,
    onArchiveUser,
    onRemoveUser,
    isCompleted,
    isSelected,
    onToggleSelect,
    archiveLabel,
    showResendEmail,
}: DraggableUserCardProps) => {
    const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
        id: user.id,
        data: {
            user,
        },
    });

    const style: CSSProperties = {
        transform: CSS.Translate.toString(transform),
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            className={isDragging ? styles.card_dragging : ''}
            {...listeners}
            {...attributes}>
            <UserCard
                user={user}
                boardId={boardId}
                onClick={onClick}
                onSelect={onSelect}
                onMoveUser={onMoveUser}
                onArchiveUser={onArchiveUser}
                onRemoveUser={onRemoveUser}
                isCompleted={isCompleted}
                isSelected={isSelected}
                onToggleSelect={onToggleSelect}
                archiveLabel={archiveLabel}
                showResendEmail={showResendEmail} />
        </div>
    );
};

