import { ReactNode, useState, useCallback, useMemo } from 'react';
import {
    DndContext,
    DragOverlay,
    DragStartEvent,
    DragEndEvent,
    DragCancelEvent,
    PointerSensor,
    KeyboardSensor,
    useSensor,
    useSensors,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { ColumnSchema, PathwayUser, PathwayPhaseId } from '../pathwayTypes';
import { UserCard } from './UserCard';
import { collisionDetection } from './dragCollision';

import styles from './PathwayDragDropContext.module.scss';

type PathwayDragDropContextProps = {
    children: ReactNode;
    onMoveUser: (user: PathwayUser, targetPhaseId: PathwayPhaseId) => void;
    selectedUserIds?: Set<string>;
    onBatchMoveUsers?: (userIds: string[], targetPhaseId: PathwayPhaseId) => void;
    onReorderColumns?: (activeColumnId: string, overColumnId: string) => void;
};

export const PathwayDragDropContext = ({
    children,
    onMoveUser,
    selectedUserIds = new Set(),
    onBatchMoveUsers,
    onReorderColumns,
}: PathwayDragDropContextProps) => {
    const [activeUser, setActiveUser] = useState<PathwayUser | null>(null);
    const [activeColumn, setActiveColumn] = useState<ColumnSchema | null>(null);

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        }),
        useSensor(KeyboardSensor, {
            coordinateGetter: sortableKeyboardCoordinates,
        })
    );

    // Check if the active user is part of a multi-selection
    const isDraggingMultiple = useMemo(() => {
        if (!activeUser || selectedUserIds.size < 2) {
            return false;
        }
        return selectedUserIds.has(activeUser.id);
    }, [activeUser, selectedUserIds]);

    const dragCount = isDraggingMultiple ? selectedUserIds.size : 1;

    const handleDragStart = useCallback((event: DragStartEvent) => {
        const data = event.active.data.current;
        if (data?.type === 'column') {
            setActiveColumn(data.column as ColumnSchema);
            return;
        }
        const user = data?.user as PathwayUser | undefined;
        if (user) {
            setActiveUser(user);
        }
    }, []);

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event;
        const activeData = active.data.current;

        // Column reorder: hand the two column ids back to the board to persist.
        if (activeData?.type === 'column') {
            const overColumn = over?.data.current?.column as ColumnSchema | undefined;
            if (overColumn && activeData.column) {
                onReorderColumns?.((activeData.column as ColumnSchema).id, overColumn.id);
            }
            setActiveColumn(null);
            return;
        }

        if (over && activeData?.user) {
            const user = activeData.user as PathwayUser;
            const targetColumnId = over.id as PathwayPhaseId;

            if (user.board.columnId !== targetColumnId) {
                // Check if we're dragging multiple selected users
                if (selectedUserIds.size >= 2 && selectedUserIds.has(user.id) && onBatchMoveUsers) {
                    // Move all selected users
                    const userIdsArray = Array.from(selectedUserIds);
                    onBatchMoveUsers(userIdsArray, targetColumnId);
                } else {
                    // Move single user
                    onMoveUser(user, targetColumnId);
                }
            }
        }

        setActiveUser(null);
    }, [onMoveUser, selectedUserIds, onBatchMoveUsers, onReorderColumns]);

    const handleDragCancel = useCallback((event: DragCancelEvent) => {
        void event;
        setActiveUser(null);
        setActiveColumn(null);
    }, []);

    return (
        <DndContext
            sensors={sensors}
            collisionDetection={collisionDetection}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
            onDragCancel={handleDragCancel}>
            {children}
            <DragOverlay dropAnimation={null}>
                {activeUser && (
                    <div className={`${styles.drag_overlay} ${isDraggingMultiple ? styles.drag_overlay_multi : ''}`}>
                        <UserCard user={activeUser} />
                        {isDraggingMultiple && (
                            <div className={styles.drag_count_badge}>
                                {dragCount}
                            </div>
                        )}
                    </div>
                )}
                {activeColumn && (
                    <div className={styles.column_drag_overlay}>{activeColumn.name}</div>
                )}
            </DragOverlay>
        </DndContext>
    );
};

