import { useState, useCallback, memo } from 'react';
import { PencilSimple, Trash, DotsSixVertical, Lightning, Info } from '@phosphor-icons/react';
import { Button, TextField } from '@mui/material';
import { useSortable } from '@dnd-kit/sortable';
import { CommonTooltip } from 'called-common/src/components/CommonTooltip';

import { AutomationsModal } from '../AutomationsModal/AutomationsModal';
import type { AutomationPhase } from '../AutomationsModal/automationsConfig';

import styles from './PhaseTitle.module.scss';

type DragHandleProps = Pick<ReturnType<typeof useSortable>, 'attributes' | 'listeners'>;

interface PhaseTitleProps {
    name: string;
    description: string;
    canEdit: boolean;
    canDelete?: boolean;
    dragHandle?: DragHandleProps;
    boardId: string;
    columnId: string;
    entityId: string;
    entityUuid: string;
    phases: AutomationPhase[];
    showAutomations?: boolean;
    hasAutomation?: boolean;
    onSave: (values: { name: string; description: string }) => Promise<void>;
    onDelete?: () => void;
}

interface PhaseTitleActionsProps {
    name: string;
    description: string;
    canEdit: boolean;
    canDelete: boolean;
    showAutomations: boolean;
    hasAutomation: boolean;
    onOpenAutomations: () => void;
    onStartEdit: () => void;
    onDelete?: () => void;
}

// The floating action cluster in the header's top-right corner, shown while
// the column is hovered (or a button inside has focus).
const PhaseTitleActionsComponent = ({
    name,
    description,
    canEdit,
    canDelete,
    showAutomations,
    hasAutomation,
    onOpenAutomations,
    onStartEdit,
    onDelete,
}: PhaseTitleActionsProps) => (
    <div className={styles.title_actions}>
        {description && (
            <CommonTooltip title={description} arrow placement="top" describeChild>
                <button
                    type="button"
                    className={styles.description_info}
                    aria-label={`Description for ${name} phase`}>
                    <Info size={16} />
                </button>
            </CommonTooltip>
        )}
        {canEdit && showAutomations && (
            <button
                type="button"
                className={`${styles.automations_button} ${hasAutomation ? styles.automations_button_active : ''}`}
                onClick={onOpenAutomations}
                aria-label={`Automations for ${name} phase`}>
                <Lightning size={16} weight={hasAutomation ? 'fill' : 'regular'} />
            </button>
        )}
        {canEdit && (
            <button
                type="button"
                className={styles.edit_button}
                onClick={onStartEdit}
                aria-label={`Edit ${name} phase`}>
                <PencilSimple size={16} />
            </button>
        )}
        {canDelete && onDelete && (
            <button
                type="button"
                className={styles.delete_button}
                onClick={onDelete}
                aria-label={`Delete ${name} phase`}>
                <Trash size={16} />
            </button>
        )}
    </div>
);

const PhaseTitleActions = memo(PhaseTitleActionsComponent);

export const PhaseTitle = ({
    name,
    description,
    canEdit,
    canDelete = false,
    dragHandle,
    boardId,
    columnId,
    entityId,
    entityUuid,
    phases,
    showAutomations = false,
    hasAutomation = false,
    onSave,
    onDelete,
}: PhaseTitleProps) => {
    const [isEditing, setIsEditing] = useState(false);
    const [draftName, setDraftName] = useState(name);
    const [draftDescription, setDraftDescription] = useState(description);
    const [isSaving, setIsSaving] = useState(false);
    const [isAutomationsOpen, setIsAutomationsOpen] = useState(false);

    const handleOpenAutomations = useCallback(() => setIsAutomationsOpen(true), []);
    const handleCloseAutomations = () => setIsAutomationsOpen(false);

    const handleStartEdit = useCallback(() => {
        setDraftName(name);
        setDraftDescription(description);
        setIsEditing(true);
    }, [name, description]);

    const handleCancel = () => setIsEditing(false);

    const handleSave = async () => {
        if (!draftName.trim()) {
            return;
        }
        setIsSaving(true);
        try {
            await onSave({ name: draftName.trim(), description: draftDescription });
            setIsEditing(false);
        } catch {
            // Saving failed — keep the editor open; the caller surfaces the error.
        } finally {
            setIsSaving(false);
        }
    };

    if (isEditing) {
        return (
            <div className={styles.edit_form}>
                <TextField
                    variant="outlined"
                    size="small"
                    label="Phase name"
                    value={draftName}
                    onChange={(event) => setDraftName(event.target.value)}
                    inputProps={{ maxLength: 255 }}
                    error={!draftName.trim()}
                    autoFocus />
                <TextField
                    variant="outlined"
                    size="small"
                    label="Description"
                    value={draftDescription}
                    onChange={(event) => setDraftDescription(event.target.value)}
                    multiline
                    minRows={2} />
                <div className={styles.edit_actions}>
                    <Button size="small" onClick={handleCancel} disabled={isSaving}>
                        Cancel
                    </Button>
                    <Button
                        size="small"
                        variant="contained"
                        onClick={handleSave}
                        disabled={isSaving || !draftName.trim()}>
                        {isSaving ? 'Saving…' : 'Save'}
                    </Button>
                </div>
            </div>
        );
    }

    return (
        <>
            <div className={styles.title_row}>
                {dragHandle && (
                    <button
                        type="button"
                        className={styles.drag_handle}
                        aria-label={`Reorder ${name} phase`}
                        {...dragHandle.attributes}
                        {...dragHandle.listeners}>
                        <DotsSixVertical size={18} />
                    </button>
                )}
                {showAutomations && hasAutomation && (
                    <Lightning
                        size={16}
                        weight="fill"
                        className={styles.automation_indicator}
                        role="img"
                        aria-label={`${name} phase has an automation`} />
                )}
                <h3 className={styles.phase_name}>{name}</h3>
            </div>
            {(canEdit || canDelete || Boolean(description)) && (
                <PhaseTitleActions
                    name={name}
                    description={description}
                    canEdit={canEdit}
                    canDelete={canDelete}
                    showAutomations={showAutomations}
                    hasAutomation={hasAutomation}
                    onOpenAutomations={handleOpenAutomations}
                    onStartEdit={handleStartEdit}
                    onDelete={onDelete} />
            )}
            <AutomationsModal
                isOpen={isAutomationsOpen}
                onClose={handleCloseAutomations}
                boardId={boardId}
                columnId={columnId}
                entityId={entityId}
                entityUuid={entityUuid}
                phases={phases} />
        </>
    );
};

