import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { usePhaseReordering } from '../usePhaseReordering';
import { ColumnSchema } from '../../pathwayTypes';

const mockEnqueueSnackbar = vi.fn();
vi.mock('notistack', () => ({
    enqueueSnackbar: (message: string, options: { variant: string }): void => {
        mockEnqueueSnackbar(message, options);
    },
}));

const mockPatch = vi.fn();
vi.mock('../../pathwayApi', () => ({
    useUpdatePathwayColumn: () => ({ mutateAsync: mockPatch }),
}));

const columns: ColumnSchema[] = [
    { id: 'a', name: 'A', description: '', color: 'FFFFFF' },
    { id: 'b', name: 'B', description: '', color: 'FFFFFF' },
    { id: 'c', name: 'C', description: '', color: 'FFFFFF' },
    { id: 'd', name: 'D', description: '', color: 'FFFFFF' },
];

const wrapper = ({ children }: { children: React.ReactNode }) => (
    <QueryClientProvider client={new QueryClient()}>{children}</QueryClientProvider>
);

const renderReordering = (overrides: { canEdit?: boolean } = {}) => {
    const refetchBoard = vi.fn().mockResolvedValue(undefined);
    const view = renderHook(
        () => usePhaseReordering({
            boardId: 'board-1',
            columns,
            canEdit: overrides.canEdit ?? true,
            refetchBoard,
        }),
        { wrapper }
    );
    return { ...view, refetchBoard };
};

describe('usePhaseReordering', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        mockPatch.mockResolvedValue(undefined);
    });

    it('persists a new index for every phase that moved', async () => {
        const { result, refetchBoard } = renderReordering();
        // Drag the last phase to the front: d,a,b,c — all four indices change.
        await act(async () => { await result.current.reorderPhase('d', 'a'); });

        expect(mockPatch).toHaveBeenCalledTimes(4);
        const sent = mockPatch.mock.calls.map((call) => {
            const args = call[0] as { pathParams: { columnId: string }; body: { order: number } };
            return { columnId: args.pathParams.columnId, order: args.body.order };
        });
        expect(sent).toEqual([
            { columnId: 'd', order: 0 },
            { columnId: 'a', order: 1 },
            { columnId: 'b', order: 2 },
            { columnId: 'c', order: 3 },
        ]);
        expect(refetchBoard).toHaveBeenCalled();
    });

    it('does nothing when editing is not allowed (system boards)', async () => {
        const { result } = renderReordering({ canEdit: false });
        await act(async () => { await result.current.reorderPhase('d', 'a'); });
        expect(mockPatch).not.toHaveBeenCalled();
    });

    it('does nothing when a phase is dropped on itself', async () => {
        const { result } = renderReordering();
        await act(async () => { await result.current.reorderPhase('b', 'b'); });
        expect(mockPatch).not.toHaveBeenCalled();
    });

    it('surfaces an error when a reorder patch fails', async () => {
        mockPatch.mockRejectedValue(new Error('boom'));
        const { result } = renderReordering();
        await act(async () => { await result.current.reorderPhase('d', 'a'); });
        expect(mockEnqueueSnackbar).toHaveBeenCalledWith(
            'Failed to reorder phases. Please try again.',
            { variant: 'error' }
        );
    });
});

