import { useState, memo } from 'react';
import { PushTriggerOption } from '@sendbird/chat';
import type { GroupChannel } from '@sendbird/chat/groupChannel';
import { useSendbirdStateContext } from '@sendbird/uikit-react';
import { useParams, useLocation } from 'wouter';
import { SpeakerSlash } from '@phosphor-icons/react';
import { useGetEntities } from 'called-api/src/openApi/calledApiComponents';
import { useResponsive } from 'called-common/src/hooks/useResponsive';
import { isMobile } from 'called-common/src/utils/platform';
import { useChannelsList } from '@/hooks/useChannelsList';
import { calledChatRoutes } from '@/utils/route';
import { useChannelAvatar } from '@/hooks/useChannelAvatar';
import { getChannelName, isDirectMessage as isDirectMessageChannel } from '@/utils/channel';
import { getChannelTimestamp } from '@/utils/date';
import { getLastMessagePreview, getMessageSenderPrefix } from '@/utils/searchHelpers';
import { ChannelAvatar } from '@/components/ChannelAvatar/ChannelAvatar';
import { UserStatusDisplay } from '@/components/UserStatusDisplay/UserStatusDisplay';
import { useDetailsPanel } from '@/components/DetailsPanel';
import { useGlobalSearchStore } from '@/stores/GlobalSearchState';
import { ChannelMenu } from '../../ChannelMenu/ChannelMenu';

import styles from './ContactPreview.module.scss';

interface ContactPreviewProps {
    channel: GroupChannel;
    dataChannelUrl?: string;
    displayNameOverride?: string;
}

export const ContactPreview = memo(({ channel, dataChannelUrl, displayNameOverride }: ContactPreviewProps) => {
    const { isMobile: isMobileResponsive } = useResponsive();
    const { setShowPanel } = useDetailsPanel();
    const clearSearch = useGlobalSearchStore((state) => state.clearSearch);
    const [menuAnchorEl, setMenuAnchorEl] = useState<null | HTMLElement>(null);
    const [menuPosition, setMenuPosition] = useState<{ x: number, y: number } | null>(null);

    const { data: entitiesData } = useGetEntities({});
    const { data: channelsData } = useChannelsList();

    const { url, unreadMessageCount, unreadMentionCount, lastMessage } = channel;
    const { channelUrl, channelAction } = useParams();
    const { stores } = useSendbirdStateContext();
    const [, setLocation] = useLocation();
    const currentUserId = stores.userStore.user.userId;
    const unreadMentionCountFormatted = unreadMentionCount > 99 ? '99+' : unreadMentionCount;
    const unreadMessageCountFormatted = unreadMessageCount > 99 ? '99+' : unreadMessageCount;

    const avatarUrl = useChannelAvatar(channel, currentUserId);
    const isPublicChannel = !entitiesData?.items?.some((entity) => entity.channelUrl === channel?.url);
    const channelApiData = channelsData?.items?.find((ch) => ch.channelUrl === channel?.url);
    const isPrivateChannel = channelApiData?.type === 'ENTITY_PRIVATE';
    const isDirectMessage = isDirectMessageChannel(channel);
    const isMuted = channel.myPushTriggerOption === PushTriggerOption.OFF;

    const messagePreview = getLastMessagePreview(lastMessage);
    const senderPrefix = getMessageSenderPrefix(lastMessage, currentUserId, isDirectMessage, channel.memberCount);
    const timestamp = lastMessage?.createdAt ? getChannelTimestamp(lastMessage.createdAt) : '';

    const handleClick = () => {
        clearSearch();
        if (isMobile || isMobileResponsive) {
            setShowPanel(true);
        }
        setLocation(`/${calledChatRoutes.chat.route}/${url}`);
    };

    const handleContextMenu = (event: React.MouseEvent<HTMLButtonElement>) => {
        event.preventDefault();
        setMenuAnchorEl(event.currentTarget);
        setMenuPosition({
            x: event.pageX,
            y: event.pageY,
        });
    };

    const renderNotification = () => {
        if (isMuted) {
            return null;
        }

        if (unreadMentionCount > 0) {
            return <div className={styles.contact__notifications}>{unreadMentionCountFormatted}</div>;
        }

        if (unreadMessageCount > 0) {
            if (isDirectMessage) {
                return <div className={styles.contact__notifications}>{unreadMessageCountFormatted}</div>;
            }

            return <div className={styles.contact__pip} />;
        }

        return null;
    };

    return (
        <>
            <button
                onClick={handleClick}
                onContextMenu={handleContextMenu}
                className={`${styles.contact} ${channelUrl === url && channelAction !== 'new' ? styles.selected : ''} ${isMuted ? styles.muted : ''}`}
                data-channel-url={dataChannelUrl} >
                <div className={styles.contact__avatar_container}>
                    <ChannelAvatar
                        imageGuid={avatarUrl}
                        size={40}
                        channel={channel}
                        isPublicChannel={isPublicChannel}
                        isPrivateChannel={isPrivateChannel} />
                    {isMuted && (
                        <div className={styles.contact__mute_icon}>
                            <SpeakerSlash size={12} weight="fill" />
                        </div>
                    )}
                </div>
                <div className={styles.contact__content}>
                    <div className={styles.contact__row_top}>
                        <div className={styles.contact__name_row}>
                            <span className={`${styles.contact__name} ${unreadMessageCount ? styles.contact__name__unread : ''}`}>
                                {displayNameOverride ?? getChannelName(channel, currentUserId)}
                            </span>
                            <UserStatusDisplay channel={channel} />
                        </div>
                        {timestamp && (
                            <span className={styles.contact__timestamp}>{timestamp}</span>
                        )}
                    </div>
                    <div className={styles.contact__row_bottom}>
                        {messagePreview && (
                            <span className={`${styles.contact__preview} ${isMuted ? styles.contact__preview__muted : ''}`}>
                                {senderPrefix && <span className={styles.contact__sender}>{senderPrefix}</span>}
                                {messagePreview}
                            </span>
                        )}
                        <div className={styles.contact__notification_container}>{renderNotification()}</div>
                    </div>
                </div>
            </button>
            <ChannelMenu
                menuAnchorEl={menuAnchorEl}
                setMenuAnchorEl={setMenuAnchorEl}
                channel={channel}
                menuPosition={menuPosition}/>
        </>
    );
});

ContactPreview.displayName = 'ContactPreview';

