import { ButtonHTMLAttributes, ReactNode } from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import { GroupChannel } from '@sendbird/chat/groupChannel';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { ChannelMenu } from '../ChannelMenu';

const mocks = vi.hoisted(() => ({
    channelsListItems: [] as Record<string, string>[],
    channelsListLoaded: true,
    invalidateQueries: vi.fn(),
    isCustomerSuccessStaff: true,
    leaveChannel: vi.fn(),
}));

vi.mock('@tanstack/react-query', () => ({
    useQueryClient: () => ({
        invalidateQueries: mocks.invalidateQueries,
    }),
}));

vi.mock('@mui/material/Menu', () => ({
    default: ({ children, open }: { children: ReactNode; open: boolean }) => open ? <div>{children}</div> : null,
}));

vi.mock('@mui/material/MenuItem', () => ({
    default: ({ children, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) => (
        <button type="button" {...props}>{children}</button>
    ),
}));

vi.mock('called-common/src/components/ConfirmationDialog', () => ({
    ConfirmationDialog: ({
        actionLabel,
        description,
        handleAction,
        open,
        title,
    }: {
        actionLabel: string;
        description: string;
        handleAction: () => void;
        open: boolean;
        title: string;
    }) => open ? (
        <div>
            <h2>{title}</h2>
            <p>{description}</p>
            <button type="button" onClick={handleAction}>{actionLabel}</button>
        </div>
    ) : null,
}));

vi.mock('called-api/src/openApi/calledApiComponents', () => ({
    useDeleteChannel: () => ({ mutate: vi.fn() }),
    useGetEntities: () => ({
        data: {
            items: [{
                id: 'community-id',
                affiliation: { role: 'ADMIN', status: 'ACTIVE' },
            }],
        },
    }),
    useGetSettings: () => ({ data: { pinnedChannels: [] } }),
    useLeaveChannel: () => ({ mutate: mocks.leaveChannel }),
    useLeaveEntity: () => ({ mutate: vi.fn() }),
    usePatchSettings: () => ({ mutate: vi.fn() }),
}));

vi.mock('@/hooks/useChannelsList', () => ({
    useChannelsList: () => ({
        data: mocks.channelsListLoaded ? { items: mocks.channelsListItems } : undefined,
        isSuccess: mocks.channelsListLoaded,
    }),
}));

vi.mock('@/hooks/useCopyInviteLink', () => ({
    useCopyInviteLink: () => ({ copyInviteLink: vi.fn() }),
}));

vi.mock('@/hooks/useIsCustomerSuccessStaff', () => ({
    useIsCustomerSuccessStaff: () => mocks.isCustomerSuccessStaff,
}));

vi.mock('@/stores/ModalStore', () => ({
    useModalStore: () => ({ openChannelInviteModal: vi.fn() }),
}));

vi.mock('../AddChannelMembersModal', () => ({
    AddChannelMembersModal: () => null,
}));

vi.mock('../ChannelMembersModal', () => ({
    ChannelMembersModal: () => null,
}));

vi.mock('../ChannelOptions/MuteChannel', () => ({
    MuteChannel: () => null,
}));

const DAY_MS = 24 * 60 * 60 * 1000;

const SUPPORT_CHANNEL_LIST_ITEM = {
    id: 'support-channel-id',
    channelUrl: 'support-channel-url',
    entityId: 'community-id',
    type: 'CUSTOMER_SUCCESS',
};

const sendbirdLeave = vi.fn();

const createCustomerSupportChannel = (createdAt = Date.now() - (29 * DAY_MS)) => ({
    createdAt,
    customType: 'CUSTOMER_SUCCESS',
    leave: sendbirdLeave,
    members: [],
    name: 'Customer Support',
    url: 'support-channel-url',
}) as unknown as GroupChannel;

const renderMenu = (channel = createCustomerSupportChannel()) => render(
    <ChannelMenu
        menuAnchorEl={document.createElement('button')}
        setMenuAnchorEl={vi.fn()}
        channel={channel} />
);

describe('ChannelMenu customer support leave action', () => {
    beforeEach(() => {
        mocks.channelsListItems = [SUPPORT_CHANNEL_LIST_ITEM];
        mocks.channelsListLoaded = true;
        mocks.invalidateQueries.mockReset();
        mocks.isCustomerSuccessStaff = true;
        mocks.leaveChannel.mockReset();
        sendbirdLeave.mockReset();
    });

    it('shows the leave action to support agents', () => {
        renderMenu();

        expect(screen.getByRole('button', { name: /Leave Customer Support Chat/i })).toBeInTheDocument();
    });

    it('does not let support agents delete a customer support chat before 30 days', () => {
        renderMenu();

        expect(screen.queryByRole('button', { name: 'Delete Channel' })).not.toBeInTheDocument();
    });

    it('lets authorized support agents delete a customer support chat after 30 days', () => {
        renderMenu(createCustomerSupportChannel(Date.now() - (31 * DAY_MS)));

        expect(screen.getByRole('button', { name: 'Delete Channel' })).toBeInTheDocument();
    });

    it('does not show the leave action to customers', () => {
        mocks.isCustomerSuccessStaff = false;

        renderMenu();

        expect(screen.queryByRole('button', { name: /Leave Customer Support Chat/i })).not.toBeInTheDocument();
    });

    it('removes the support agent through the channel leave endpoint', () => {
        mocks.leaveChannel.mockImplementation((_request, options: { onSuccess: () => void }) => {
            options.onSuccess();
        });
        renderMenu();

        fireEvent.click(screen.getByRole('button', { name: /Leave Customer Support Chat/i }));
        fireEvent.click(screen.getByRole('button', { name: 'Leave' }));

        expect(mocks.leaveChannel).toHaveBeenCalledWith(
            { pathParams: { channelId: 'support-channel-id' } },
            expect.objectContaining({ onSuccess: expect.any(Function) })
        );

        expect(mocks.invalidateQueries).toHaveBeenCalledWith({ queryKey: ['v1', 'channel'] });
        expect(sendbirdLeave).not.toHaveBeenCalled();
    });

    it('shows the leave action when the chat has no backend record', () => {
        mocks.channelsListItems = [];

        renderMenu();

        expect(screen.getByRole('button', { name: /Leave Customer Support Chat/i })).toBeInTheDocument();
    });

    it('leaves through Sendbird when the chat has no backend record', () => {
        mocks.channelsListItems = [];

        renderMenu();

        fireEvent.click(screen.getByRole('button', { name: /Leave Customer Support Chat/i }));
        fireEvent.click(screen.getByRole('button', { name: 'Leave' }));

        expect(sendbirdLeave).toHaveBeenCalled();
        expect(mocks.leaveChannel).not.toHaveBeenCalled();
    });

    it('does not offer the leave action until the channel list has loaded', () => {
        mocks.channelsListLoaded = false;

        renderMenu();

        expect(screen.queryByRole('button', { name: /Leave Customer Support Chat/i })).not.toBeInTheDocument();
    });
});

