import { useEffect, useState } from 'react';
import type { GroupChannel } from '@sendbird/chat/groupChannel';

export const useChannelAvatar = (channel?: GroupChannel, currentUserId?: string) => {
    const [avatarUrl, setAvatarUrl] = useState<string | string[]>('');

    useEffect(() => {
        if (channel?.customType === 'User' && channel.memberCount >= 2) {
            setAvatarUrl(
                channel.members
                    .filter(member => member.userId !== currentUserId)
                    .map(member => member.profileUrl)
            );
        } else {
            setAvatarUrl(channel?.coverUrl ?? '');
        }
    }, [channel, currentUserId]);

    return avatarUrl;
};

