import { CSSProperties } from 'react';
import { GroupChannel } from '@sendbird/chat/groupChannel';
import { UserOnlineState } from '@sendbird/chat';
import CalledLogo from 'called-common/src/assets/CalledLogos/LogoDark.svg';
import CalledLogoLight from 'called-common/src/assets/CalledLogos/LogoLight.svg';
import { isCustomerSuccessChannel } from '@/utils/channel';
import { useIsCustomerSuccessStaff } from '@/hooks/useIsCustomerSuccessStaff';
import { useThemeDetector } from '@/hooks/useThemeDetector';
import { SendbirdAvatar } from '@/components/SendbirdAvatar/SendbirdAvatar';

import styles from './ChannelAvatar.module.scss';

interface ChannelAvatarProps {
    imageGuid?: string | string[];
    size?: number;
    className?: string;
    channel?: GroupChannel;
    memberActiveStatus?: UserOnlineState;
    isPublicChannel?: boolean;
    isPrivateChannel?: boolean;
}

export const ChannelAvatar = (props: ChannelAvatarProps) => {
    const { channel, size, className } = props;
    const isCustomerSuccessStaff = useIsCustomerSuccessStaff();
    const showCalledTeamBranding = Boolean(channel) && isCustomerSuccessChannel(channel as GroupChannel) && !isCustomerSuccessStaff;
    const isDarkTheme = useThemeDetector();
    const logo = isDarkTheme ? CalledLogoLight : CalledLogo;

    if (showCalledTeamBranding) {
        const sizeStyle = { '--avatar-size': size ? `${size}px` : undefined } as CSSProperties;
        return (
            <div className={styles.avatar} style={sizeStyle}>
                <img
                    className={`${className ?? ''} ${styles.called_team_logo}`}
                    src={logo}
                    alt="Called Team avatar"
                    width={size}
                    height={size} />
            </div>
        );
    }

    return <SendbirdAvatar {...props} />;
};

