import { AddChannelMembersModal } from './AddChannelMembersModal';
import { MuteChannel } from './ChannelOptions/MuteChannel';

const CUSTOMER_SUPPORT_DELETE_AGE_MS = 30 * 24 * 60 * 60 * 1000;

interface LeavePermissions {
    canLeaveApiChannel: boolean;
    canLeaveChannel: boolean;
    canLeaveCustomerSupportChat: boolean;
}

const canDeleteChannel = (
    channel: GroupChannel,
    communityEntity: EntitySchema | null | undefined,
    isCustomerSupportChat: boolean,
    isPublicChannel: boolean
): boolean => {
    if (!isPublicChannel || !communityEntity || !hasLeaderOrAdminPermission(communityEntity)) {
        return false;
    }

    if (!isCustomerSupportChat) {
        return true;
    }

    return channel.createdAt > 0
        && Date.now() - channel.createdAt >= CUSTOMER_SUPPORT_DELETE_AGE_MS;
};

const canAddChannelMembers = (
    channelData: ChannelSchema | undefined,
    communityEntity: EntitySchema | null | undefined
): boolean => {
    const isNewEntityChannel = channelData?.type === 'ENTITY_PUBLIC' || channelData?.type === 'ENTITY_PRIVATE';
    return !!isNewEntityChannel && !!communityEntity && hasLeaderOrAdminPermission(communityEntity);
};

const getLeavePermissions = (
    channelData: ChannelSchema | undefined,
    communityEntity: EntitySchema | null | undefined,
    entity: EntitySchema | undefined,
    isChannelsListLoaded: boolean,
    isCustomerSupportChat: boolean,
    isCustomerSuccessStaff: boolean,
    isDirectMessage: boolean
): LeavePermissions => {
    const isPublicChannel = !entity;
    const isLeaderOrAdmin = !!communityEntity && hasLeaderOrAdminPermission(communityEntity);
    const canLeavePublicChannel = isPublicChannel && channelData?.type === 'ENTITY_PUBLIC';
    const canLeavePrivateChannel = isPublicChannel && channelData?.type === 'ENTITY_PRIVATE' && !isLeaderOrAdmin;
    const canLeaveEntityChannel = canLeavePublicChannel || canLeavePrivateChannel;
    // Wait for the channels query so a still-loading (or failed) list is never
    // mistaken for "no backend record", which would leave via Sendbird only and
    // strand the backend membership.
    const canLeaveCustomerSupportChat = isChannelsListLoaded && isCustomerSupportChat && isCustomerSuccessStaff;
    const canLeaveApiChannel = canLeaveEntityChannel || canLeaveCustomerSupportChat;

    return {
        canLeaveApiChannel,
        canLeaveChannel: isDirectMessage || entity?.affiliation?.role === 'MEMBER' || canLeaveApiChannel,
        canLeaveCustomerSupportChat,
    };
};

const getLeaveTitle = (
    canLeaveApiChannel: boolean,
    canLeaveCustomerSupportChat: boolean,
    groupType: string,
    isDirectMessage: boolean
): string => {
    if (isDirectMessage) {
        return localization.chat.chatOptions.leaveChat.leaveDirectMessage;
    }
    if (canLeaveCustomerSupportChat) {
        return 'Leave Customer Support Chat';
    }
    if (canLeaveApiChannel) {
        return 'Leave Channel';
    }
    return `Leave ${groupType}`;
};

const getLeaveDescription = (
    canLeaveApiChannel: boolean,
    channel: GroupChannel,
    entity: EntitySchema | undefined,
    isDirectMessage: boolean
): string => {
    if (isDirectMessage) {
        return localization.chat.chatOptions.leaveChat.confirmationDialog.description;
    }
    if (canLeaveApiChannel) {
        return `Are you sure you want to leave ${channel.name || 'this channel'}?`;
    }
    return `Are you sure you want to leave ${entity?.name}?`;
};

interface ChannelMenuProps {
    menuAnchorEl: HTMLElement | null;
    setMenuAnchorEl: (anchor: HTMLElement | null) => void;
    channel?: GroupChannel;
    menuPosition?: { x: number; y: number } | null;
}

interface ChannelMenuActionsProps {
    canAddMembers: boolean;
    canDelete: boolean;
    canLeave: boolean;
    channel: GroupChannel;
    channelData: ChannelSchema | undefined;
    communityEntity: EntitySchema | null | undefined;
    entity: EntitySchema | undefined;
    handleClose: () => void;
    handlePinChannel: () => void;
    isChannelPinned: boolean;
    leaveTitle: string;
    onAddMembers: () => void;
    onCopyInviteLink: () => void;
    onDelete: () => void;
    onInviteMembers: () => void;
    onLeave: () => void;
    onViewMembers: () => void;
}

const ChannelMenuActions = ({
    canAddMembers,
    canDelete,
    canLeave,
    channel,
    channelData,
    communityEntity,
    entity,
    handleClose,
    handlePinChannel,
    isChannelPinned,
    leaveTitle,
    onAddMembers,
    onCopyInviteLink,
    onDelete,
    onInviteMembers,
    onLeave,
    onViewMembers,
}: ChannelMenuActionsProps) => (
    <>
        <MenuItem className='menu_item' onClick={handleClose} onClickCapture={onViewMembers}>
            <Users size={20} /> {canAddMembers ? 'Manage Members' : 'View Members'}
        </MenuItem>
        {canAddMembers && (
            <MenuItem className='menu_item' onClick={handleClose} onClickCapture={onAddMembers}>
                <UserPlus size={20} /> Add Members
            </MenuItem>
        )}
        {canAddMembers && channelData?.id && communityEntity && (
            <MenuItem className='menu_item' onClick={handleClose} onClickCapture={onInviteMembers}>
                <EnvelopeSimple size={20} /> Invite Members
            </MenuItem>
        )}
        {entity && (
            <MenuItem className='menu_item' onClick={handleClose} onClickCapture={onCopyInviteLink}>
                <Link size={16} /> Copy Invite Link
            </MenuItem>
        )}
        <MenuItem className='menu_item' onClick={handleClose} onClickCapture={handlePinChannel}>
            <PushPin size={20} />
            {isChannelPinned ? 'Unpin Channel' : 'Pin Channel'}
        </MenuItem>
        <MuteChannel handleClose={handleClose} sendbirdChannel={channel} />
        {canDelete && (
            <MenuItem onClick={handleClose} className='menu_item menu_danger' onClickCapture={onDelete}>
                <Trash size={20} />
                Delete Channel
            </MenuItem>
        )}
        {canLeave && (
            <MenuItem onClick={handleClose} className='menu_item menu_danger' onClickCapture={onLeave}>
                <DoorOpen size={20} />
                {leaveTitle}
            </MenuItem>
        )}
    </>
);

export const ChannelMenu = memo((props: ChannelMenuProps) => {
    const { menuAnchorEl, setMenuAnchorEl, channel, menuPosition } = props;
    const [isLeaveDialogOpen, setIsLeaveDialogOpen] = useState(false);
    const [isMembersModalOpen, setIsMembersModalOpen] = useState(false);
    const [isAddMembersModalOpen, setIsAddMembersModalOpen] = useState(false);
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);

    const queryClient = useQueryClient();
    const { data: settings } = useGetSettings({});
    const { mutate: patchSettings } = usePatchSettings();
    const { data: getEntitiesData } = useGetEntities({});
    const { data: channelsData, isSuccess: isChannelsListLoaded } = useChannelsList();
    const { mutate: leaveEntity } = useLeaveEntity();
    const { mutate: deleteChannel } = useDeleteChannel();
    const { mutate: leaveChannel } = useLeaveChannel();
    const { openChannelInviteModal } = useModalStore();
    const isCustomerSuccessStaff = useIsCustomerSuccessStaff();
    const entity = getEntitiesData?.items.find((ent) => ent.channelUrl === channel?.url);

    const { copyInviteLink } = useCopyInviteLink({ entityId: entity?.id || '' });

    useEffect(() => {
        const handleGlobalClick = (event: MouseEvent) => {
            if (
                !event.target ||
                !(event.target as Element).closest('[data-channel-url]') ||
                event.target !== menuAnchorEl
            ) {
                setMenuAnchorEl(null);
            }
        };

        if (menuAnchorEl) {
            document.addEventListener('mousedown', handleGlobalClick);
        }

        return () => {
            document.removeEventListener('mousedown', handleGlobalClick);
        };
    }, [menuAnchorEl, setMenuAnchorEl]);

    const handleClose = () => {
        setMenuAnchorEl(null);
    };

    if (!channel) {
        return null;
    }

    const isMenuOpen = Boolean(menuAnchorEl);
    const isDirectMessage = channel.customType === 'User';
    const groupType = entity?.type === 'GROUP' ? "Group" : "Community";
    const { buttonLabel } = localization.chat.chatOptions.leaveChat.confirmationDialog;
    const isPublicChannel = !entity;

    // Find the channel in our API data and get its community
    const channelData = channelsData?.items.find((ch) => ch.channelUrl === channel.url);
    const communityEntity = channelData?.entityId
        ? getEntitiesData?.items.find((ent) => ent.id === channelData.entityId)
        : null;
    const isCustomerSupportChat = isCustomerSuccessChannel(channel);
    const canAddMembers = canAddChannelMembers(channelData, communityEntity);
    const canDelete = canDeleteChannel(channel, communityEntity, isCustomerSupportChat, isPublicChannel);
    const { canLeaveApiChannel, canLeaveChannel, canLeaveCustomerSupportChat } = getLeavePermissions(
        channelData,
        communityEntity,
        entity,
        isChannelsListLoaded,
        isCustomerSupportChat,
        isCustomerSuccessStaff,
        isDirectMessage
    );
    const leaveTitle = getLeaveTitle(canLeaveApiChannel, canLeaveCustomerSupportChat, groupType, isDirectMessage);
    const leaveDescription = getLeaveDescription(canLeaveApiChannel, channel, entity, isDirectMessage);

    const handleLeaveChannelConfirmation = () => {
        if (isDirectMessage) {
            void channel?.leave();
        } else if (canLeaveApiChannel && channelData?.id) {
            void leaveChannel(
                { pathParams: { channelId: channelData.id } },
                {
                    onSuccess: () => {
                        void queryClient.invalidateQueries({ queryKey: ['v1', 'channel'] });
                    },
                }
