            return <PrayersInbox />;
        }

        if (listLoading && !searchTerm) {
            return <ContactListLoading />;
        }

        if (searchTerm && searchFilteredChannels.length === 0) {
            return (
                <div className="contact_list__no-results">
                    <p>No channels found matching {searchTerm}</p>
                </div>
            );
        }

        if (filteredChannelList.length === 0 && activeFilter !== 'all' && !showCalledTeamSection) {
            return (
                <div className="contact_list__no-results">
                    <p>{getEmptyFilterMessage(activeFilter)}</p>
                </div>
            );
        }

        return <ChannelList
            channels={searchFilteredChannels}
            pinnedChannels={filteredPinnedChannels}
            isSearchActive={hasActiveSearch} />;
    };

    return (
        <>
            <ContactHeader
                searchTerm={searchTerm}
                onSearchChange={handleSearch}
                onFilterChange={handleFilterChange}
                activeFilter={activeFilter}
                unreadCount={totalUnreadCount}
                customerSupportUnreadCount={customerSupportUnreadCount}
                hasCustomerSupportChannels={hasCustomerSupportChannels} />
            {!(isMobile && hasActiveSearch) && (
                <div className="contact_list__wrapper" data-clarity-mask="true">
                    <div className="contact_list__content">
…
                    </div>
                </div>
            )}
        </>
    );

