import { useEffect, useRef, useState } from 'react';
import {
    DndContext,
    DragEndEvent,
    KeyboardSensor,
    PointerSensor,
    closestCenter,
    useSensor,
    useSensors,
} from '@dnd-kit/core';
import { arrayMove, SortableContext, sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { PushTriggerOption } from '@sendbird/chat';
import { BaseMessage } from '@sendbird/chat/message';
import { useSendbirdStateContext } from '@sendbird/uikit-react';
import { GroupChannel } from '@sendbird/chat/groupChannel';
import { useParams } from 'wouter';
import { useChannelsList } from '@/hooks/useChannelsList';
import { useResponsive } from 'called-common/src/hooks/useResponsive';
import { log } from 'called-common/src/utils/logger';
import { useChannelNotificationStatus } from '@/hooks/useChannelNotificationStatus';
import { useServiceWorker } from '@/hooks/useServiceWorker';
import { useDetailsPanel } from '@/components/DetailsPanel';
import { getChannelName } from '@/utils/channel';
import { ContactPreview } from './ContactPreview';
import { PinnedEditRow } from './PinnedEditRow';

// Extend the SendBird message type... the sendbird types are wrong.
interface ExtendedMessage extends BaseMessage {
    message: string;
    sender: {
        userId: string;
        nickname: string;
    };
}

type ChannelListProps = {
    channels: GroupChannel[];
    pinnedChannels: string[];
    isSearchActive?: boolean;
}

const REFRESH_INTERVAL = 5000;
const HIDDEN_REFRESH_INTERVAL = 2000;

export const ChannelList = ({ channels, pinnedChannels, isSearchActive = false }: ChannelListProps) => {
    const channelListRef = useRef<HTMLDivElement>(null);
    const { channelUrl } = useParams();
    const initialScrollRef = useRef(false);
    const prevShowPanelRef = useRef(false);
    const { stores } = useSendbirdStateContext();
    const { showPanel } = useDetailsPanel();
    const { isMobile } = useResponsive();

    // Pre-fetching this data for the channel menu that can be accessed from the channel list.
    // useChannelsList raises the /v1/channel page size so channels past the first 100 are included.
    useChannelsList();

    const currentUserId = stores.userStore.user.userId;
    const previousChannelsRef = useRef<Record<string, { unreadCount: number, lastMessageTime?: number }>>({});

    const { registration: notificationWorker, ready: workerReady } = useServiceWorker();
    const updateNotificationStatus = useChannelNotificationStatus({ updateFavicon: true });

    // Desktop only: Scrolls to the selected channel if we land on the page with a channelUrl
    useEffect(() => {
        if (!isMobile && channelUrl && channelListRef.current && !initialScrollRef.current) {
            const selectedChannel = channelListRef.current.querySelector(`[data-channel-url="${channelUrl}"]`);
            if (selectedChannel) {
                selectedChannel.scrollIntoView({ block: 'nearest' });
                initialScrollRef.current = true;
            }
        }
    }, [channelUrl]);

    // Mobile only: scroll to selected channel when backing out of a conversation
    useEffect(() => {
        if (isMobile && prevShowPanelRef.current && !showPanel && channelUrl && channelListRef.current) {
            const selectedChannel = channelListRef.current.querySelector(`[data-channel-url="${channelUrl}"]`);
            if (selectedChannel) {
                selectedChannel.scrollIntoView({ block: 'nearest' });
            }
        }
        prevShowPanelRef.current = showPanel;
    }, [isMobile, showPanel, channelUrl]);

    // Setup periodic refresh for status updates
    useEffect(() => {
        const updateStatus = () => {
            updateNotificationStatus(channels);

            channels.forEach(channel => {
                const prev = previousChannelsRef.current[channel.url];
                const hasNewMessages = prev && (
                    channel.unreadMessageCount > prev.unreadCount ||
                    (channel.lastMessage?.createdAt && prev.lastMessageTime &&
                        channel.lastMessage.createdAt > prev.lastMessageTime)
                );

                // Only show notifications for the channel we don't have selected
                if (hasNewMessages && (channel.url !== channelUrl || document.hidden)) {
                    const isDirectMessage = !channel.name || channel.name === 'Group Channel';
                    const { lastMessage } = channel;

                    // Check if user is mentioned
                    const isMentioned = lastMessage?.mentionedUserIds?.some(userId => userId === currentUserId);

                    if ((isDirectMessage || isMentioned) && lastMessage &&
                        channel.myPushTriggerOption !== PushTriggerOption.OFF &&
                        workerReady) {

                        const typedMessage = lastMessage as ExtendedMessage;
                        if (Notification.permission === 'granted' && notificationWorker?.active && typedMessage.sender.userId !== currentUserId) {
                            // Title is the name of the other users
                            let title = channel.members
                                .filter(el => el.userId !== currentUserId)
                                .map(el => el.nickname)
                                .join(' , ') || 'New Message';

                            // get profile url that's not the current user
                            let icon = channel.members
                                .filter(el => el.userId !== currentUserId)
                                .map(el => el.profileUrl)[0];

                            if (isMentioned) {
                                // use the icon of the user who mentioned the current user
                                icon = channel.members.find(el => el.userId === typedMessage.sender.userId)?.profileUrl || '';

                                // If not a direct or group channel use the name of the channel
                                if (!isDirectMessage) {
                                    title = channel.name;
                                }
                            }

                            try {
                                notificationWorker.active.postMessage({
                                    type: 'SHOW_NOTIFICATION',
                                    data: {
                                        title,
                                        body: `${typedMessage.sender.nickname}: ${typedMessage.message}` || 'New message received',
                                        icon,
                                        channelUrl: channel.url
                                    }
                                });
                            } catch (error) {
                                log.error('Failed to send notification message', error);
                            }
                        }
                    }
                }

                previousChannelsRef.current[channel.url] = {
                    unreadCount: channel.unreadMessageCount,
                    lastMessageTime: channel.lastMessage?.createdAt
                };
            });
        };

        void updateStatus();
        // If the tab isn't active refresh every 2 seconds instead of every 5 seconds
        const intervalId = setInterval(() => void updateStatus(), document.hidden ? HIDDEN_REFRESH_INTERVAL : REFRESH_INTERVAL);
        return () => clearInterval(intervalId);
    }, [channels, currentUserId]);

    return (
        <div className="contact_list__wrapper">
            <div className="contact_list_groups" ref={channelListRef}>
                {channels.map((channel, index) => {
                    const isPinned = pinnedChannels.includes(channel.url);
                    const showAllChatsHeading = !isSearchActive && !isPinned && (
                        index === 0 || pinnedChannels.includes(channels[index - 1]?.url)
                    );

                    return (
                        <div key={channel.url}>
                            {showAllChatsHeading && (
                                <div className='contact_list__section_heading contact_list__all_chats_heading'>
                                    <span>ALL CHATS</span>
                                </div>
                            )}
                            <ContactPreview
                                channel={channel}
                                dataChannelUrl={channel.url} />
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

