    it('does not offer the leave action until the channel list has loaded', () => {
        mocks.channelsListLoaded = false;

        renderMenu();

        expect(screen.queryByRole('button', { name: /Leave Customer Support Chat/i })).not.toBeInTheDocument();
    });
});

describe('ChannelMenu pin channel writes', () => {
    beforeEach(() => {
        mocks.patchSettings.mockReset();
        mocks.settings = { pinnedChannels: [] };
    });

    it('pins a channel by appending to the end and renumbering', () => {
        // D was pinned first but left at order 3 after earlier unpins; the new
        // pin must sort below it, so it gets order 2, not the old collision-y
        // "pinnedChannels.length" that would place it above D.
        mocks.settings = {
            pinnedChannels: [
                { channel: 'ch-a', order: 0 },
                { channel: 'ch-d', order: 3 },
            ],
        };
        renderMenu(createChannel('ch-new'));

        fireEvent.click(screen.getByRole('button', { name: 'Pin Channel' }));

        expect(mocks.patchSettings).toHaveBeenCalledWith(
            expect.objectContaining({
                body: {
                    pinnedChannels: [
                        { channel: 'ch-a', order: 0 },
                        { channel: 'ch-d', order: 1 },
                        { channel: 'ch-new', order: 2 },
                    ],
                },
            }),
            expect.anything()
        );
    });

    it('unpins a channel and renumbers the remaining pins', () => {
        mocks.settings = {
            pinnedChannels: [
                { channel: 'ch-a', order: 0 },
                { channel: 'ch-b', order: 1 },
                { channel: 'ch-d', order: 3 },
            ],
        };
        renderMenu(createChannel('ch-b'));

        fireEvent.click(screen.getByRole('button', { name: 'Unpin Channel' }));

        expect(mocks.patchSettings).toHaveBeenCalledWith(
            expect.objectContaining({
                body: {
                    pinnedChannels: [
                        { channel: 'ch-a', order: 0 },
                        { channel: 'ch-d', order: 1 },
                    ],
                },
            }),
            expect.anything()
        );
    });

    it('pins a channel to an empty list as order 0', () => {
        renderMenu(createChannel('ch-first'));

        fireEvent.click(screen.getByRole('button', { name: 'Pin Channel' }));

        expect(mocks.patchSettings).toHaveBeenCalledWith(
            expect.objectContaining({
                body: {
                    pinnedChannels: [{ channel: 'ch-first', order: 0 }],
                },
            }),
            expect.anything()
        );
    });
});

